        rows=[('2024-01-01T00:15:00+02:30','2023-12-31T21:45:00Z'),('2024-12-31T23:40:00-01:30','2025-01-01T01:10:00Z'),('2024-02-29T00:00:00+00:20','2024-02-28T23:40:00Z'),('2025-03-03T18:50:00-04:00','2025-03-03T22:50:00Z'),('2025-06-07T08:09:10Z','2025-06-07T08:09:10Z')]
        for s,w in rows:self.assertEqual(app.to_utc(s),w)


