class HostTimezone(unittest.TestCase):
    def test_explicit_utc_in_different_host_zones(self):
        import os, time
        original = os.environ.get('TZ')
        try:
            for zone in ['UTC0', 'EST5EDT', 'JST-9']:
                os.environ['TZ'] = zone
                time.tzset()
                self.assertEqual(app.to_utc('2001-01-01T00:05:07+00:15'), '2000-12-31T23:50:07Z')
                self.assertEqual(app.to_utc('2025-12-31T23:55:00-00:15'), '2026-01-01T00:10:00Z')
                self.assertEqual(app.to_utc('2025-04-01T00:01:02+00:00'), '2025-04-01T00:01:02Z')
        finally:
            if original is None: os.environ.pop('TZ', None)
            else: os.environ['TZ'] = original
            time.tzset()

